for i in range(210000, 285001):
    even_divs = []
    for d in range(1, int(i**0.5) + 1):
        if i % d == 0:
            # d - первый делитель
            if d % 2 == 0: even_divs.append(d)
            # i//d - второй делитель
            d2 = i // d
            if d2 != d and d2 % 2 == 0:
                even_divs.append(d2)

    if len(even_divs) >= 120:
        print(len(even_divs), max(even_divs))

for x in range(210000, 285001):
    divs = set()
    for d in range(1, int(x**0.5) + 1):
        if x % d == 0:
            if d % 2 == 0: divs.add(d)
            if (x // d) % 2 == 0: divs.add(x // d)
    if len(divs) >= 120:
        print(len(divs), max(divs))
